import{_ as e,o as s,c as r,ag as n}from"./chunks/framework.DKalukzk.js";const p=JSON.parse('{"title":"Grille d’évaluation — TP2","description":"Grille critériée — Outil de budget mensuel (Excel)","frontmatter":{"title":"Grille d’évaluation — TP2","description":"Grille critériée — Outil de budget mensuel (Excel)","aside":true},"headers":[],"relativePath":"grilles/grille-tp2-excel-budget.md","filePath":"grilles/grille-tp2-excel-budget.md"}'),i={name:"grilles/grille-tp2-excel-budget.md"};function o(l,t,d,a,u,c){return s(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="grille-d-evaluation-—-tp2" tabindex="-1">Grille d’évaluation — TP2 <a class="header-anchor" href="#grille-d-evaluation-—-tp2" aria-label="Permalink to &quot;Grille d’évaluation — TP2&quot;">​</a></h1><p><strong>Outil de budget mensuel (Excel)</strong></p><blockquote><p><strong>Échelle descriptive</strong><br><strong>Excellent = 100 %</strong> · <strong>Bien = 80 %</strong> · <strong>Correct = 60 %</strong> · <strong>Insuffisant = 40 %</strong> · <strong>Invalide = 0 %</strong></p></blockquote><hr><h2 id="_1-gabarit-—-formules-et-robustesse-20" tabindex="-1">1) Gabarit — Formules et robustesse (20 %) <a class="header-anchor" href="#_1-gabarit-—-formules-et-robustesse-20" aria-label="Permalink to &quot;1) Gabarit — Formules et robustesse (20 %)&quot;">​</a></h2><p><strong>Tests fonctionnels</strong></p><ul><li>Les cellules jaunes contiennent des <strong>formules</strong> (aucun calcul manuel)</li><li>Les totaux (revenus, dépenses fixes) affichent <strong>0,00 $</strong> lorsque vides</li><li>Aucune erreur Excel (<code>#DIV/0!</code>, <code>#N/A</code>, etc.)</li><li>Format monétaire appliqué aux cellules d’argent principales</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Toutes les formules sont présentes, robustes et sans erreur.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Fonctionnement correct avec de légers détails mineurs.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Fonctionnement partiel, quelques erreurs ou fragilités.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Plusieurs erreurs ou formules manquantes.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Gabarit non fonctionnel ou calculs manuels.</td><td>0 %</td></tr></tbody></table><hr><h2 id="_2-dates-du-mois-budget-mensuel-et-budget-journalier-15" tabindex="-1">2) Dates du mois, budget mensuel et budget journalier (15 %) <a class="header-anchor" href="#_2-dates-du-mois-budget-mensuel-et-budget-journalier-15" aria-label="Permalink to &quot;2) Dates du mois, budget mensuel et budget journalier (15 %)&quot;">​</a></h2><p><strong>Tests fonctionnels</strong></p><ul><li>Les dates <strong>Du</strong> et <strong>Au</strong> s’ajustent automatiquement selon le mois affiché</li><li>Le <strong>budget mensuel</strong> est calculé par formule (revenus − dépenses fixes)</li><li>Le <strong>budget journalier</strong> est calculé par formule (budget mensuel ÷ nombre de jours du mois)</li><li>Test rapide : changer le mois → dates et budgets se recalculent</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Dates et budgets automatisés et correctement recalculés.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Calculs automatisés avec légères imperfections.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Calculs corrects pour le mois affiché, adaptation limitée.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Calculs partiellement incorrects ou partiellement manuels.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Dates ou budgets incorrects ou absents.</td><td>0 %</td></tr></tbody></table><hr><h2 id="_3-categories-et-liste-deroulante-validation-de-donnees-10" tabindex="-1">3) Catégories et liste déroulante (validation de données) (10 %) <a class="header-anchor" href="#_3-categories-et-liste-deroulante-validation-de-donnees-10" aria-label="Permalink to &quot;3) Catégories et liste déroulante (validation de données) (10 %)&quot;">​</a></h2><p><strong>Tests fonctionnels</strong></p><ul><li>La table des catégories est remplie (budgets mensuels)</li><li>La colonne <strong>Catégorie</strong> utilise une <strong>liste déroulante</strong></li><li>Les choix correspondent aux catégories définies</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Liste déroulante complète et correctement liée aux catégories.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Liste fonctionnelle avec détails mineurs.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Liste partielle ou liaison imparfaite.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Liste peu fonctionnelle ou incohérente.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Absence de liste déroulante fonctionnelle.</td><td>0 %</td></tr></tbody></table><hr><h2 id="_4-statistiques-et-mise-en-forme-conditionnelle-15" tabindex="-1">4) Statistiques et mise en forme conditionnelle (15 %) <a class="header-anchor" href="#_4-statistiques-et-mise-en-forme-conditionnelle-15" aria-label="Permalink to &quot;4) Statistiques et mise en forme conditionnelle (15 %)&quot;">​</a></h2><p><strong>Tests fonctionnels</strong></p><ul><li>Statistiques calculées à partir de la liste de dépenses : <ul><li>moyenne</li><li>plus grosse dépense</li><li>plus petite dépense</li><li>total des dépenses</li></ul></li><li>Mise en forme conditionnelle sur le <strong>total des dépenses</strong> : <ul><li>rouge si le total dépasse le budget mensuel</li><li>vert si le total est inférieur ou égal au budget mensuel</li></ul></li><li>Test rapide : modifier une dépense → la couleur s’ajuste</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Statistiques exactes et mise en forme conditionnelle fonctionnelle.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Statistiques exactes avec légers écarts de présentation.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Statistiques partiellement exactes ou mise en forme imparfaite.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Plusieurs statistiques incorrectes ou mise en forme absente.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Statistiques absentes ou non fonctionnelles.</td><td>0 %</td></tr></tbody></table><hr><h2 id="_5-donnees-saisies-—-coherence-et-variete-10" tabindex="-1">5) Données saisies — Cohérence et variété (10 %) <a class="header-anchor" href="#_5-donnees-saisies-—-coherence-et-variete-10" aria-label="Permalink to &quot;5) Données saisies — Cohérence et variété (10 %)&quot;">​</a></h2><p><strong>Tests fonctionnels</strong></p><ul><li>La feuille de travail est une <strong>copie du gabarit</strong></li><li>Des données sont saisies (revenus, dépenses fixes, dépenses)</li><li>Plusieurs catégories sont utilisées</li><li>Il peut y avoir plusieurs dépenses pour une même date</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Données complètes, variées et cohérentes.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Données adéquates avec légère répétition ou manque de variété.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>Données présentes mais peu exploitables.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Données incomplètes ou incohérentes.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Données absentes ou feuille incorrecte.</td><td>0 %</td></tr></tbody></table><hr><h2 id="_6-tcd-—-depenses-par-jour-et-mise-en-forme-conditionnelle-15" tabindex="-1">6) TCD — Dépenses par jour et mise en forme conditionnelle (15 %) <a class="header-anchor" href="#_6-tcd-—-depenses-par-jour-et-mise-en-forme-conditionnelle-15" aria-label="Permalink to &quot;6) TCD — Dépenses par jour et mise en forme conditionnelle (15 %)&quot;">​</a></h2><p><strong>Tests fonctionnels</strong></p><ul><li>Feuille dédiée correctement nommée</li><li>TCD : <ul><li>lignes : Date</li><li>valeurs : Somme de Dépense</li></ul></li><li>Mise en forme conditionnelle : <ul><li>la ligne devient rouge si la somme de dépenses d’une date dépasse le budget journalier</li></ul></li><li>Test rapide : modifier une dépense → la ligne réagit</li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>TCD correct et mise en forme conditionnelle fonctionnelle.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>TCD correct avec mise en forme partielle ou imparfaite.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>TCD correct sans mise en forme fonctionnelle.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>TCD partiellement correct ou mal structuré.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>TCD absent ou non fonctionnel.</td><td>0 %</td></tr></tbody></table><hr><h2 id="_7-tcd-—-depenses-par-categorie-graphique-et-impression-15" tabindex="-1">7) TCD — Dépenses par catégorie, graphique et impression (15 %) <a class="header-anchor" href="#_7-tcd-—-depenses-par-categorie-graphique-et-impression-15" aria-label="Permalink to &quot;7) TCD — Dépenses par catégorie, graphique et impression (15 %)&quot;">​</a></h2><p><strong>Tests fonctionnels</strong></p><ul><li>Feuille dédiée correctement nommée</li><li>TCD : <ul><li>lignes : Catégorie</li><li>valeurs : Somme de Dépense</li></ul></li><li>Graphique circulaire : <ul><li>titre explicite</li><li>valeurs affichées</li></ul></li><li>Mise en page : <ul><li>TCD et graphique tiennent sur une page, en mode portrait</li></ul></li></ul><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>TCD et graphique complets, lisibles et prêts à l’impression.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>TCD et graphique corrects avec ajustements mineurs.</td><td>80 %</td></tr><tr><td><strong>Correct</strong></td><td>TCD correct, graphique ou mise en page partielle.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>TCD ou graphique incomplet ou peu lisible.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>TCD et graphique absents ou non fonctionnels.</td><td>0 %</td></tr></tbody></table><hr><h2 id="respect-des-consignes-et-modalites-de-remise-penalite" tabindex="-1">Respect des consignes et modalités de remise (pénalité) <a class="header-anchor" href="#respect-des-consignes-et-modalites-de-remise-penalite" aria-label="Permalink to &quot;Respect des consignes et modalités de remise (pénalité)&quot;">​</a></h2><p><strong>Tests fonctionnels</strong></p><ul><li>Fichier au format <strong>.xlsx</strong></li><li><strong>Exactement 4 feuilles</strong></li><li>Noms des feuilles conformes aux consignes</li></ul><table tabindex="0"><thead><tr><th>Situation observée</th><th>Pénalité appliquée</th></tr></thead><tbody><tr><td>Toutes les consignes sont respectées</td><td><strong>0 %</strong></td></tr><tr><td>Oublis mineurs ou incohérences</td><td><strong>−5 %</strong></td></tr><tr><td>Non-respect important des consignes</td><td><strong>−10 %</strong></td></tr></tbody></table><hr><h2 id="retard-dans-la-remise-penalite" tabindex="-1">Retard dans la remise (pénalité) <a class="header-anchor" href="#retard-dans-la-remise-penalite" aria-label="Permalink to &quot;Retard dans la remise (pénalité)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Retard observé</th><th>Pénalité appliquée</th></tr></thead><tbody><tr><td>≤ 24 h</td><td><strong>−10 %</strong></td></tr><tr><td>≤ 48 h</td><td><strong>−20 %</strong></td></tr><tr><td>≤ 72 h</td><td><strong>−30 %</strong></td></tr><tr><td>Plus de 72 h</td><td><strong>Travail refusé</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>La pénalité pour retard s’applique <strong>après</strong> l’évaluation des critères et <strong>s’additionne</strong>, s’il y a lieu, à la pénalité pour non-respect des consignes.</p></div>',47)])])}const h=e(i,[["render",o]]);export{p as __pageData,h as default};
